// Test fixture dependency. Lives under a committed node_modules/ dir so capwall attributes
// its calls to "fixture-dep". Requires fs at load time — tests must require this module
// INSIDE the patched window (and clear the require cache between windows) so it receives
// the shimmed fs.
const fs = require("fs");
const fsPromises = require("fs/promises");
const path = require("path");

const DATA = path.join(__dirname, "data.txt");

exports.readData = () => fs.readFileSync(DATA, "utf8");
exports.readDataAsync = () => fsPromises.readFile(DATA, "utf8");
exports.writeFile = (target) => fs.writeFileSync(target, "fixture-dep was here\n");
exports.rawReadFileSync = fs.readFileSync; // for testing that uninstall/teardown behaves

// Reads DATA via the ReadStream CONSTRUCTOR (not createReadStream) — the bypass surface.
// Returns a promise of the file contents; rejects if construction is denied.
exports.readViaStreamClass = () =>
  new Promise((resolve, reject) => {
    let stream;
    try {
      stream = new fs.ReadStream(DATA);
    } catch (err) {
      reject(err);
      return;
    }
    let data = "";
    stream.on("data", (c) => (data += c));
    stream.on("end", () => resolve(data));
    stream.on("error", reject);
  });

// Existence probe — must return a boolean, never throw, even when denied.
exports.probeExists = () => fs.existsSync(DATA);

// Reads a process.env key — the anti-exfiltration surface. Attributes to "fixture-dep".
exports.readEnv = (key) => process.env[key];

// M4 capability surfaces, each via require() so the loader registry is exercised.
exports.connect = (host, port) => {
  const net = require("net");
  const socket = net.connect({ host, port });
  socket.on("error", () => {}); // ignore ECONNREFUSED; we only care whether the guard fired
  socket.destroy();
  return socket;
};
exports.spawn = () => require("child_process").spawnSync(process.execPath, ["-e", ""]);
exports.runVm = (code) => require("vm").runInNewContext(code);
